from rcb_client import Robot
import numpy as np
r=Robot(); o=r.get_obs(cameras=['robot0_agentview_center','robot0_eye_in_hand'],video='none')
for c in o.meta['cameras']:
 K=np.array(o.meta['cameras'][c]['intrinsic_cv']); T=np.array(o.meta['cameras'][c]['cam2world_gl'])@np.diag([1,-1,-1,1]);
 print(c)
 for p in [[3.0761,-.4893,.989],[3.06964,-.48782,1.20946],[3.06964,-.48782,1.1],[3.06964,-.48782,.99]]:
  q=np.linalg.inv(T)@np.r_[p,1]; uv=K@(q[:3]/q[2]); print(p,'cam',np.round(q[:3],3),'uv',np.round(uv[:2],1))
PY

