const r=await tools.exec_command({cmd:"python - <<'PY'
from rcb_client import Robot
import numpy as np
from PIL import Image
r=Robot();o=r.get_obs(cameras=['robot0_eye_in_hand'],include_depth=True,video='none');c='robot0_eye_in_hand';im=o.last[c].astype(int); d=o.depth[c][0].astype(float);K=np.array(o.meta['cameras'][c]['intrinsic_cv']);T=np.array(o.meta['cameras'][c]['cam2world_gl'])@np.diag([1,-1,-1,1]);Image.fromarray(o.last[c]).save('/app/output/lift_current_hand.png')
y,x=np.mgrid[:240,:320]; mask=(x>105)&(x<220)&(y>70)&(y<205)&(im[:,:,0]>170)&(im[:,:,1]>130)&(im[:,:,2]<145)&(im[:,:,0]>im[:,:,1]*1.04)&(im[:,:,1]>im[:,:,2]*1.3)&(d>0.05)&(d<0.2)
yy,xx=np.where(mask);print('n',len(xx),'uv',xx.mean(),yy.mean(),'bounds',xx.min(),xx.max(),yy.min(),yy.max(),'depth',np.median(d[yy,xx]));
pts=[]
for u,v in zip(xx,yy):
 z=d[v,u];q=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);pts.append((T@q)[:3])
pts=np.array(pts);print('world med',np.median(pts,axis=0),'world mean',pts.mean(0),'eef',o.meta['proprio']['now'][26:29]);
PY",yield_time_ms:30000,max_output_tokens:300}); text(r.output);
