import numpy as np
r=Robot();o=r.get_obs(cameras=['robot0_eye_in_hand'],include_depth=True,video='none'); c='robot0_eye_in_hand';im=o.last[c].astype(int);d=o.depth[c][0].astype(float);K=np.array(o.meta['cameras'][c]['intrinsic_cv']);T=np.array(o.meta['cameras'][c]['cam2world_gl'])@np.diag([1,-1,-1,1]);
print('eef',o.meta['proprio']['now'][26:29], 'cam',T[:3,3]);
for v in [170,180,190,200,210,220,230]:
 row=[]
 for u in [120,135,145,155,165,175,185,195,205,215,230]:
  z=float(np.median(d[max(0,v-1):v+2,max(0,u-1):u+2]));pix=im[v,u];q=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);w=T@q
  row.append(f'{u}:{pix[0]},{pix[1]},{pix[2]} d{z:.2f} w{w[0]:.2f},{w[1]:.2f},{w[2]:.2f}')
 print('v',v,' | '.join(row))
